'use strict';
const C=WordJournal,V=VocabularyCore,S=StudyCore,I=ImportCore;
const KEY='read-and-keep-demo-v1';
const $=(s,scope=document)=>scope.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Tabler Icons (MIT), stored locally so icons do not depend on a CDN.
const iconNames=new Set(['book','logo','sun','repeat','plus','arrow','chevron','calendar','star','check','close','search','leaf','settings','edit','download','trash','note','clock','spark','undo','user','cloud','upload']);
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><use href="assets/icons.svg#${iconNames.has(name)?name:'book'}"></use></svg>`;}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}

let state,storageOK=true;
try{state=S.upgrade(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{state=S.upgrade({});storageOK=false;}
initializeReader();
let route='today',filter='all',groupBy='date',query='',sourceFilter='',notebookFilter='',session=null,toastTimer;
let draft={source:'',batch:'',format:'txt',rows:[],preview:false},dialogState=null,studyRevealed=false,studyRunning=false;
let persistedState=JSON.parse(JSON.stringify(state));
function persist(){try{state=S.upgrade(state);if(window.CloudSession)window.CloudSession.save(state);else localStorage.setItem(KEY,JSON.stringify(state));persistedState=JSON.parse(JSON.stringify(state));storageOK=true;return true;}catch(e){state=JSON.parse(JSON.stringify(persistedState));storageOK=false;toast('暂时无法保存：'+e.message);return false;}}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function today(){return S.day(new Date().toISOString());}
function shortDate(key){if(!key)return '—';const p=String(key).slice(0,10).split('-');return `${Number(p[1])} 月 ${Number(p[2])} 日`;}
function dateLabel(key){return key===today()?'今天':key===C.addDays(today(),-1)?'昨天':shortDate(key);}
function countWords(){return V.groups(state).length;}
function sourceGroups(){return [...new Set(state.entries.map(e=>e.source))].map(name=>({name}));}
function navHTML(){return [['today','sun','今天'],['notebooks','book','词汇册'],['read','note','文章'],['library','book','生词本'],['review','repeat','学习']].map(([id,i,label])=>`<a href="#${id}" class="nav-btn ${route===id||(id==='notebooks'&&notebookFilter)?'active':''}" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');}
function footer(){return `<footer class="page-footer"><button class="text-link" data-action="about">关于拾词</button></footer>`;}
function intro(kicker,title,subtitle,action=''){return `<div class="page-intro"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`;}
function empty(title,description='',label='',action=''){return `<div class="empty">${icon('book')}<h2>${title}</h2>${description?`<p>${description}</p>`:''}${label?`<button class="btn primary" data-action="${action}">${label}</button>`:''}</div>`;}
function weekHTML(){const weekday=new Date(today()+'T12:00:00+08:00').getUTCDay()||7,start=C.addDays(today(),1-weekday);return Array.from({length:7},(_,i)=>{const key=C.addDays(start,i),done=S.activity(state,key);return `<div class="day-cell"><div class="day-circle ${done?'done':''} ${key===today()?'current':''}" title="${key}${done?' 有学习记录':''}">${done?icon('check'):'一二三四五六日'[i]}</div><span>${Number(key.slice(-2))}</span></div>`;}).join('');}
function home(){const stats=S.stats(state),due=S.queue(state,'unknown','english'),books=V.books(state);return `${intro('','今天',shortDate(today()))}<section class="overview" aria-label="学习概览"><div class="review-banner"><div class="banner-copy"><h2>${icon('repeat')}生词回顾</h2><div class="review-total"><strong>${due.length}</strong><span>今日待学习</span></div><button class="btn primary" data-action="start-review">${due.length?'开始回顾':'查看学习'}${icon('arrow')}</button></div><img class="growth-art" src="assets/reading-growth.png" width="256" height="256" alt=""></div><div class="summary-card"><h2 class="summary-title">学习记录${icon('calendar')}</h2><div class="stats"><div class="stat"><strong>${stats.added}</strong><span>今日新增词汇</span></div><div class="stat"><strong>${stats.reviewed}</strong><span>今日已学习</span></div></div><div class="goal-line">每日目标 <span>${Math.min(stats.reviewed,stats.goal)} / ${stats.goal}</span></div><progress class="daily-progress" max="${stats.goal}" value="${stats.reviewed}" aria-label="每日学习完成进度"></progress><div class="week" aria-label="本周学习记录">${weekHTML()}</div></div></section><div class="totals-strip"><span><strong>${stats.total}</strong> 不同词汇</span><span><strong>${stats.records}</strong> 来源记录</span><span><strong>${stats.articles}</strong> 文章</span></div><section><div class="section-heading"><h2>词汇册<span class="count">${books.length}</span></h2><a class="text-link" href="#notebooks">全部词汇册${icon('arrow')}</a></div>${books.length?`<div class="notebook-grid">${books.slice(0,4).map(notebookCard).join('')}</div>`:empty('暂无词汇册','','记录词汇','record-words')}</section>${footer()}`;}
function notebookDate(book){const date=new Date(book.createdAt);return Number.isNaN(date.getTime())?'':date.toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false});}
function notebookCard(book){return `<a class="notebook-card" href="#library?book=${encodeURIComponent(book.id)}" aria-label="打开词汇册 ${esc(book.title)}"><div class="notebook-cover"><span class="notebook-kind">${icon('book')}${esc(book.kind)}</span><div class="notebook-total"><strong>${V.groups(state,false,book.entries).length}</strong><span>个词汇</span></div><div class="notebook-preview">${[...new Set(book.entries.map(e=>e.word))].slice(0,3).map(w=>`<span>${esc(w)}</span>`).join('')}</div></div><div class="notebook-card-body"><h3>${esc(book.title)}</h3><div class="notebook-meta"><time>${esc(notebookDate(book))}</time>${icon('arrow')}</div></div></a>`;}
function notebooks(){const books=V.books(state);return `${intro('','词汇册',`${books.length} 册`, '<button class="btn primary" data-action="record-words">'+icon('plus')+'记录词汇</button>')}${books.length?`<div class="notebook-grid">${books.map(notebookCard).join('')}</div>`:empty('暂无词汇册')}${footer()}`;}
function currentNotebook(){return V.books(state).find(b=>b.id===notebookFilter);}
function libraryEntries(){return notebookFilter?currentNotebook()?.entries||[]:state.entries.filter(e=>V.isUnknown(state,e.word));}
function filteredEntries(){const q=query.trim().toLowerCase();return libraryEntries().filter(e=>(filter!=='unknown'||V.isUnknown(state,e.word))&&(!sourceFilter||e.notebookId===sourceFilter)&&(!q||[e.word,e.meaning,e.source,e.sentence,e.note].join(' ').toLowerCase().includes(q)));}
function filteredGroups(){return V.groups(state,false,filteredEntries());}
function wordCard(group){const e=group.entries[0],selected=bulkSelected.has(group.key),unknown=V.isUnknown(state,e.word);return `<article class="word-card ${bulkMode&&selected?'bulk-selected':''}"><div class="word-top">${bulkMode?`<label class="bulk-word-choice"><input type="checkbox" data-bulk-entry="${esc(group.key)}" aria-label="选择 ${esc(e.word)}" ${selected?'checked':''}><span class="word">${esc(e.word)}</span></label>`:`<button class="word-link" data-action="detail" data-id="${esc(e.id)}"><span class="word">${esc(e.word)}</span></button><button class="icon-btn ${unknown?'is-unknown':''}" data-action="mark-word" data-word="${esc(group.key)}" aria-label="${unknown?'移出生词本':'加入生词本'} ${esc(e.word)}" aria-pressed="${unknown}">${icon(unknown?'check':'plus')}</button>`}</div>${e.phonetic?`<div class="phonetic">${esc(e.phonetic)}</div>`:''}<div class="meaning">${esc(e.meaning)||'<span class="muted">释义待补充</span>'}</div><p class="sentence">${sentenceHTML(e)}</p><div class="card-footer"><span class="source">${icon('book')}${esc(state.notebooks.find(b=>b.id===e.notebookId)?.title||e.source)}</span><span class="seen-tag">${state.entries.filter(x=>V.key(x.word)===group.key).length} 个来源</span></div></article>`;}
function libraryResults(){const groups=filteredGroups();return (bulkMode?bulkControls(groups):'')+(groups.length?`<div class="small muted" role="status">${groups.length} 个词汇 · ${filteredEntries().length} 条来源记录</div><div class="library-grid">${groups.map(wordCard).join('')}</div>`:empty(notebookFilter?'本册暂无匹配词汇':'暂无生词'));}
function library(){const book=currentNotebook();if(notebookFilter&&!book)return empty('词汇册已不存在');const actions=`<div class="library-intro-actions">${book?`<button class="btn" data-action="rename-book">${icon('edit')}改名</button><button class="btn danger ghost" data-action="delete-book">${icon('trash')}删除词汇册</button>`:''}<button class="btn" data-bulk="toggle">${icon('settings')}${bulkMode?'完成管理':'批量管理'}</button><button class="btn" data-action="export-options">${icon('download')}导出</button></div>`;return `${book?'<a class="text-link notebook-breadcrumb" href="#notebooks">'+icon('book')+'词汇册</a>':''}${intro('',esc(book?.title||'生词本'),book?`${book.entries.length} 条来源记录 · ${notebookDate(book)}`:`${V.groups(state,true).length} 个生词`,actions)}${book?.articleId?`<button class="btn soft" data-action="notebook-read">${icon('note')}打开文章</button>`:''}<div class="library-toolbar"><label class="search-wrap">${icon('search')}<input id="search" type="search" aria-label="搜索词汇、释义或原句" placeholder="搜索词汇、释义或原句" value="${esc(query)}"></label>${!book?`<select id="source-filter" aria-label="筛选词汇册"><option value="">全部词汇册</option>${V.books(state).map(b=>`<option value="${esc(b.id)}" ${sourceFilter===b.id?'selected':''}>${esc(b.title)}</option>`).join('')}</select>`:''}</div>${book?`<div class="pills filter-row">${[['all','全部词汇'],['unknown','已加入生词本']].map(([id,label])=>`<button class="pill ${filter===id?'active':''}" data-action="filter" data-filter="${id}">${label}</button>`).join('')}</div>`:''}<div id="library-results">${libraryResults()}</div>${footer()}`;}
function recordDialog(){dialogState='record';showDialog('记录',`<div class="record-choices"><button class="record-choice" data-action="record-words">${icon('book')}<strong>记录词汇</strong><small>粘贴 / TXT / CSV</small></button><button class="record-choice" data-action="import-article">${icon('note')}<strong>记录文章</strong><small>PDF / Word / 粘贴</small></button></div>`);}
function captureDraft(){if(dialogState!=='add')return;draft.source=$('#entry-source')?.value??draft.source;draft.batch=$('#batch-input')?.value??draft.batch;}
function addDialog(){dialogState='add';showDialog('记录词汇',`<form id="add-form"><div class="form-row"><label for="entry-source">词汇册名称</label><input id="entry-source" required maxlength="150" value="${esc(draft.source)}"></div>${draft.preview?`<div class="import-preview"><div class="section-heading"><h3>确认词汇</h3><span>${draft.rows.length} 条</span></div><table><thead><tr><th>词汇</th><th>释义</th><th>原句</th></tr></thead><tbody>${draft.rows.map(r=>`<tr><td>${esc(r.word)}</td><td>${esc(r.meaning)||'—'}</td><td>${esc(r.sentence)||'—'}</td></tr>`).join('')}</tbody></table></div><p class="field-hint">保存到词汇册后，可选出需要加入生词本的词。</p><button type="button" class="text-link" data-action="back-import">返回编辑</button>`:`<label class="file-upload-zone" for="word-file">${icon('upload')}选择 TXT / CSV 文件<input id="word-file" type="file" accept=".txt,.csv,text/plain,text/csv"></label><div class="form-row"><label for="word-format">内容格式</label><select id="word-format"><option value="txt" ${draft.format==='txt'?'selected':''}>TXT：用 | 分隔</option><option value="csv" ${draft.format==='csv'?'selected':''}>CSV：用逗号分隔</option></select><label for="batch-input">词汇清单</label><textarea id="batch-input" rows="8" maxlength="500000" placeholder="每行一个词：词汇 | 释义 | 原句">${esc(draft.batch)}</textarea><p class="field-hint">TXT 用 | 分隔；CSV 依次为词汇、释义、原句三列。最多 1,000 条。</p></div>`}<p id="add-error" class="error" role="alert"></p><div class="form-footer"><button class="btn primary" type="submit">${draft.preview?'保存词汇册':'检查词汇'}${icon('arrow')}</button></div></form>`);}
function detail(id){const first=state.entries.find(e=>e.id===id);if(!first)return;dialogState='detail';$('#modal').dataset.entry=id;const entries=state.entries.filter(e=>V.key(e.word)===V.key(first.word)),p=S.progress(state,first.word),unknown=V.isUnknown(state,first.word);showDialog('词汇详情',`<div class="detail-hero"><h3 class="word">${esc(first.word)}</h3><button class="btn soft" data-action="mark-word" data-word="${esc(first.word)}">${icon(unknown?'check':'plus')}${unknown?'移出生词本':'加入生词本'}</button><p class="small muted">已学习 ${p.reviews} 次${p.reviews?' · 下次 '+shortDate(p.due):''}</p></div>${entries.map(e=>`<section class="source-detail"><h3>${esc(state.notebooks.find(b=>b.id===e.notebookId)?.title||'来源记录')}</h3><p class="detail-meta">${esc(e.source)} · ${shortDate(e.created)}</p><p class="meaning">${esc(e.meaning)||'释义待补充'}</p><p class="sentence">${sentenceHTML(e)}</p>${readerDetailExtra(e)}${e.note?`<p class="detail-note">${esc(e.note)}</p>`:''}<div class="detail-actions"><button class="text-link" data-action="edit" data-id="${esc(e.id)}">${icon('edit')}编辑来源</button><button class="text-link danger" data-action="delete-prompt" data-id="${esc(e.id)}">${icon('trash')}删除来源记录</button></div></section>`).join('')}`);}
function renameBookDialog(){const b=currentNotebook();dialogState='rename-book';showDialog('修改词汇册名称',`<form id="book-name-form" data-id="${esc(b.id)}"><div class="form-row"><label for="book-name">词汇册名称</label><input id="book-name" name="title" value="${esc(b.title)}" required maxlength="150"></div><p class="error" id="book-error" role="alert"></p><button class="btn primary">保存名称</button></form>`);}
function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(){download(JSON.stringify({app:'拾词',version:3,exportedAt:new Date().toISOString(),...state},null,2),'application/json;charset=utf-8',`拾词完整备份-${today()}.json`);toast('完整备份已导出');}
function exportOptions(){dialogState='export';showDialog('导出',`<form id="export-form"><div class="form-row"><label for="export-range">导出范围</label><select id="export-range" name="range"><option value="all">全部生词</option><option value="filtered">当前筛选结果</option><option value="selected" ${bulkSelected.size?'':'disabled'}>所选词汇（${bulkSelected.size}）</option></select></div><p class="field-hint">CSV 保留所选词汇的全部来源、释义、原句和笔记。</p><button class="btn primary">导出 CSV</button></form><div class="form-footer"><button class="btn" data-action="export">完整 JSON 备份</button></div>`);}
function changeMark(words,value){state=V.mark(state,words,value);if(!persist())return;render();if(dialogState==='detail')detail($('#modal').dataset.entry);toast(value?'已加入生词本':'已移出生词本，词汇册和学习记录保留');}
function studyOptions(){return `<form id="study-form" class="study-options"><div class="form-row"><label for="study-scope">学习范围</label><select id="study-scope" name="scope"><option value="all" ${state.settings.studyScope==='all'?'selected':''}>全部词汇</option><option value="unknown" ${state.settings.studyScope!=='all'?'selected':''}>全部生词</option></select></div><div class="form-row"><label for="study-mode">记忆方式</label><select id="study-mode" name="mode">${[['english','看英文回忆释义'],['meaning','看释义回忆英文'],['cloze','原句填空']].map(([v,l])=>`<option value="${v}" ${state.settings.studyMode===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-row"><label for="daily-amount">每日学习数量</label><input id="daily-amount" type="number" name="amount" min="1" max="200" value="${state.settings.dailyAmount}" required></div><p class="field-hint">没有释义的词需先补充；原句填空只练习有对应原句的词。</p><button class="btn primary" type="submit">${S.current(state)?'继续学习':'开始学习'}${icon('arrow')}</button></form>`;}
function review(){const c=S.current(state),header=intro('','学习','',studyRunning?'<button class="btn" data-action="study-options">学习设置</button>':'');if(!studyRunning)return header+`<div class="review-wrap">${studyOptions()}</div>`+footer();if(!c)return header+`<div class="review-wrap">${empty('本次学习完成',`今日已学习 ${S.stats(state).reviewed} 个词汇`,'选择学习范围','study-options')}</div>`+footer();const e=c.entry,mode=c.session.mode,p=S.progress(state,e.word);const prompt=mode==='english'?e.word:mode==='meaning'?e.meaning:S.cloze(e);const context=mode==='english'?e.sentence:mode==='meaning'?S.cloze(e):'';return `${header}<div class="review-wrap"><div class="review-topline"><span>${c.session.scope==='unknown'?'全部生词':'全部词汇'} · ${c.index+1} / ${c.session.items.length}</span><span>${['看英文回忆释义','看释义回忆英文','原句填空'][S.modes.indexOf(mode)]}</span></div><progress class="daily-progress" max="${c.session.items.length}" value="${c.index}" aria-label="本次学习进度"></progress><article class="review-card"><h2 class="${mode==='cloze'?'sentence':'word'}">${esc(prompt)}</h2>${context?`<p class="sentence study-context">${esc(context)}</p>`:''}<p class="small muted">${esc(e.source)}</p>${studyRevealed?`<div class="study-answer"><h3>${mode==='english'?'释义':'词汇'}</h3><p class="meaning">${esc(mode==='english'?e.meaning:e.word)}</p>${mode==='cloze'?`<p>${esc(e.meaning)}</p><p class="sentence">${sentenceHTML(e)}</p>`:''}${e.sentenceTranslation?`<p class="small muted">${esc(e.sentenceTranslation)}</p>`:''}</div>`:''}</article>${studyRevealed?`<div class="review-actions">${[['forgot','忘记'],['vague','模糊'],['remember','记得']].map(([g,l])=>`<button class="btn ${g==='remember'?'primary':''}" data-action="study-grade" data-grade="${g}">${l}<small>${S.schedule(p,g,new Date().toISOString()).interval} 天后</small></button>`).join('')}</div>`:'<button class="btn primary reveal-button" data-action="study-reveal">显示答案</button>'}</div>${footer()}`;}
function render(){const [page,params='']=location.hash.slice(1).split('?');route=['today','notebooks','read','library','review'].includes(page)?page:'today';const nextNotebook=route==='library'?new URLSearchParams(params).get('book')||'':'';if(nextNotebook!==notebookFilter){query='';sourceFilter='';filter='all';bulkMode=false;bulkSelected.clear();}notebookFilter=nextNotebook;document.body.dataset.page=route;$('#desktop-nav').innerHTML=navHTML();$('#mobile-nav').innerHTML=navHTML();$('#main').innerHTML=route==='today'?home():route==='notebooks'?notebooks():route==='read'?readerPage():route==='library'?library():review();$('#brand-icon').innerHTML=icon('logo');hydrateIcons();readerAfterRender();bulkAfterRender();window.CloudSession?.refreshStatus();}
function navigate(next){if(location.hash==='#'+next)render();else location.hash=next;}
function showDialog(title,body){const d=$('#modal');$('#modal-content').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();}
function closeDialog(){$('#modal').close();dialogState=null;}

function sentenceHTML(e){if(!e.sentence)return '<span class="muted">暂无原句</span>';const escapedWord=e.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const re=new RegExp('('+escapedWord+')','gi');return e.sentence.split(re).map((s,i)=>i%2?`<mark>${esc(s)}</mark>`:esc(s)).join('');}
function edit(id){const e=state.entries.find(x=>x.id===id);if(!e)return;dialogState='edit';showDialog('编辑生词',`<form id="edit-form" data-id="${id}" data-initial-meaning="${esc(e.meaning)}"><div class="form-row"><label for="edit-word">单词或短语</label><input id="edit-word" name="word" value="${esc(e.word)}" required maxlength="150"></div><div class="form-row"><label for="edit-meaning">本文释义</label><input id="edit-meaning" name="meaning" value="${esc(e.meaning)}" maxlength="500"></div><div class="form-row"><label for="edit-sentence">原句</label><textarea id="edit-sentence" name="sentence" rows="3" maxlength="10000">${esc(e.sentence)}</textarea></div><div class="form-row"><label for="edit-source">文章来源</label><input id="edit-source" name="source" value="${esc(e.source)}" maxlength="150"></div><div class="form-row"><label for="edit-note">我的笔记</label><textarea id="edit-note" name="note" rows="2" maxlength="3000">${esc(e.note)}</textarea></div><p id="edit-error" class="error" role="alert"></p><div class="form-footer"><button type="submit" class="btn primary">保存修改 ${icon('check')}</button></div></form>`);}
function about(){dialogState='about';showDialog('关于拾词',`<div class="about-mark">${icon('logo')}</div><div class="about-section"><h3>数据保存</h3><p>访客记录仅保存在当前浏览器。登录后可跨设备读取已同步的文章、生词和回顾记录；未同步内容仍在本机。</p></div><div class="about-section"><h3>翻译与词典</h3><p>所选词发送至 FreeDictionaryAPI；词语、原句、词典释义与例句发送至 MyMemory 翻译，不发送全文。机器翻译可手动修改。</p></div><div class="about-section"><h3>文章与备份</h3><p>文章文件在本机解析，登录后的文章正文保存到 Supabase。清理浏览器数据前，请同步或导出记录。</p></div><div class="form-footer"><button class="btn" data-action="export">${icon('download')}导出备份</button></div>`);}

document.addEventListener('click',ev=>{
 const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='add'){recordDialog();return;}
 if(a==='record-words'){addDialog();return;}
 if(a==='import-article'){importDialog();return;}
 if(a==='close'){captureDraft();captureArticleDraft();if(dialogState==='import'){importTicket++;articleDraft.busy=false;}closeDialog();return;}
 if(a==='about'){about();return;}
 if(a==='detail'){detail(id);return;}
 if(a==='edit'){edit(id);return;}
 if(a==='export'){exportData();return;}
 if(a==='export-options'){exportOptions();return;}
 if(a==='mark-word'){changeMark([el.dataset.word],!V.isUnknown(state,el.dataset.word));return;}
 if(a==='rename-book'){renameBookDialog();return;}
 if(a==='filter'){filter=el.dataset.filter;render();return;}
 if(a==='back-import'){captureDraft();draft.preview=false;addDialog();return;}
 if(a==='notebook-read'){state.activeArticle=currentNotebook()?.articleId;if(persist())navigate('read');return;}
 if(a==='delete-book'){const b=currentNotebook();dialogState='delete-book';showDialog('删除词汇册？',`<p>将删除「${esc(b.title)}」及其中 ${b.entries.length} 条来源记录与笔记。其他词汇册、文章原文和学习历史保留。</p><button class="btn danger" data-action="confirm-delete-book" data-id="${esc(b.id)}">确认删除词汇册</button>`);return;}
 if(a==='confirm-delete-book'){if(dialogState!=='delete-book')return;const ids=state.entries.filter(e=>e.notebookId===id).map(e=>e.id);state=V.removeRecords(state,ids);state.notebooks=state.notebooks.filter(b=>b.id!==id);if(!persist())return;ids.forEach(cancelEntryTranslation);closeDialog();navigate('notebooks');return;}
 if(a==='delete-prompt'){const e=state.entries.find(e=>e.id===id);if(!e)return;dialogState='delete';showDialog('删除来源记录？',`<p>将删除 ${esc(e.word)} 在「${esc(e.source)}」中的释义、原句和笔记。其他来源、词汇册和学习历史保留。</p><button class="btn danger" data-action="delete" data-id="${esc(id)}">确认删除来源记录</button>`);return;}
 if(a==='delete'){if(dialogState!=='delete')return;if(deleteRecordIds([id])===null)return;closeDialog();render();return;}
 if(a==='start-review'){state.settings.studyScope='unknown';state.settings.studyMode='english';state=S.start(state,{scope:'unknown',mode:'english'});if(!persist())return;studyRunning=Boolean(S.current(state));studyRevealed=false;navigate('review');return;}
 if(a==='study-options'){studyRunning=false;studyRevealed=false;render();return;}
 if(a==='study-reveal'){studyRevealed=true;render();return;}
 if(a==='study-grade'){if(!studyRevealed)return;state=S.answer(state,el.dataset.grade);if(!persist())return;studyRevealed=false;render();return;}
});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){query=ev.target.value;$('#library-results').innerHTML=libraryResults();bulkSync();}if(ev.target.id==='batch-input'){draft.batch=ev.target.value;}if(ev.target.id==='entry-source')draft.source=ev.target.value;});
document.addEventListener('change',async ev=>{
 if(ev.target.id==='word-format')draft.format=ev.target.value;
 if(ev.target.id==='source-filter'){sourceFilter=ev.target.value;$('#library-results').innerHTML=libraryResults();bulkSync();}
 if(ev.target.id==='word-file'){const file=ev.target.files[0];if(!file)return;const owner=window.CloudSession?.identity();try{if(file.size>1024*1024)throw new Error('词汇文件最多 1 MB。');if(!/\.(txt|csv)$/i.test(file.name))throw new Error('请选择 TXT 或 CSV 文件。');const text=await file.text();if(dialogState!=='add'||window.CloudSession?.identity()!==owner)return;draft.batch=text;draft.format=/\.csv$/i.test(file.name)?'csv':'txt';draft.source=draft.source||file.name.replace(/\.[^.]+$/,'');addDialog();}catch(e){if($('#add-error'))$('#add-error').textContent=e.message;}}
});
document.addEventListener('submit',ev=>{
 const form=ev.target;if(form.id==='add-form'){ev.preventDefault();captureDraft();try{V.validateTitle(state,draft.source);if(!draft.preview){draft.rows=V.prepareRows(I.parse(draft.batch,draft.format));if(!draft.rows.length)throw new Error('请至少输入一个词。');if(draft.rows.some(r=>!r.word||r.word.length>150))throw new Error('词汇不能为空，且每条最多 150 字符。');draft.preview=true;addDialog();return;}const id=V.uid();state=V.importWords(state,draft.source,draft.rows,{id});if(!persist())return;draft={source:'',batch:'',format:'txt',rows:[],preview:false};closeDialog();navigate('library?book='+encodeURIComponent(id));toast('词汇册已保存');}catch(e){$('#add-error').textContent=e.message;}}
 if(form.id==='book-name-form'){ev.preventDefault();try{state=V.renameBook(state,form.dataset.id,new FormData(form).get('title'));if(!persist())return;closeDialog();render();}catch(e){$('#book-error').textContent=e.message;}}
 if(form.id==='edit-form'){ev.preventDefault();const f=new FormData(form),id=form.dataset.id,word=f.get('word').trim();if(!word)return;const original=state.entries.find(e=>e.id===id),unknown=V.isUnknown(state,original.word);cancelEntryTranslation(id);state.entries=state.entries.map(e=>e.id!==id?e:{...e,word,meaning:f.get('meaning').trim(),sentence:f.get('sentence').trim(),source:f.get('source').trim()||e.source,note:f.get('note').trim(),meaningEdited:true,translationStatus:'manual',translationVersion:(e.translationVersion||0)+1,...(word!==e.word||f.get('sentence').trim()!==e.sentence?{lexicon:null,sentenceTranslation:'',locationStale:true}:{})});if(!state.vocabulary.some(v=>v.id===V.key(word)))state.vocabulary.push({id:V.key(word),isUnknown:unknown});if(!persist())return;render();detail(id);}
 if(form.id==='export-form'){ev.preventDefault();const range=new FormData(form).get('range'),keys=new Set(range==='all'?V.groups(state,true).map(g=>g.key):range==='selected'?[...bulkSelected]:filteredGroups().map(g=>g.key));const entries=state.entries.filter(e=>keys.has(V.key(e.word))).map(e=>({...e,notebookTitle:state.notebooks.find(b=>b.id===e.notebookId)?.title||''}));download(I.csv(entries),'text/csv;charset=utf-8',`拾词-${today()}.csv`);toast(`已导出 ${keys.size} 个词汇、${entries.length} 条来源记录`);}
 if(form.id==='study-form'){ev.preventDefault();const f=new FormData(form);state.settings={...state.settings,dailyAmount:Math.max(1,Math.min(200,Number(f.get('amount'))||20)),studyScope:f.get('scope'),studyMode:f.get('mode')};state=S.start(state,{scope:f.get('scope'),mode:f.get('mode')});if(!persist())return;studyRunning=true;studyRevealed=false;render();}
});
$('#modal').addEventListener('cancel',()=>{captureDraft();captureArticleDraft();if(dialogState==='import'){importTicket++;articleDraft.busy=false;}});
window.addEventListener('hashchange',()=>{studyRevealed=false;render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',ev=>{if(ev.key===KEY&&ev.newValue&&(!window.CloudSession||window.CloudSession.ownsGuest())){try{state=S.upgrade(JSON.parse(ev.newValue));persistedState=JSON.parse(JSON.stringify(state));studyRevealed=false;render();}catch{}}});
render();
if(!storageOK)setTimeout(()=>toast('浏览器存储不可用，请导出备份'),500);
